# group foreground cells 1/2 by 8-connectivity; majority label

def groups8(grid, foreground):
 H,W=grid.shape; seen=set(); groups=[]
 for r in range(H):
  for c in range(W):
   if grid[r,c] in foreground and (r,c) not in seen:
    q=[(r,c)];seen.add((r,c));g=[]
    while q:
     a,b=q.pop();g.append((a,b))
     for dr in [-1,0,1]:
      for dc in [-1,0,1]:
       x,y=a+dr,b+dc
       if (dr or dc) and 0<=x<H and 0<=y<W and grid[x,y] in foreground and (x,y) not in seen:
        seen.add((x,y));q.append((x,y))
    groups.append(g)
 return groups

def pred_network(grid,out,target,region_colors,bg):
