  cnt=Counter(grid[r,c] for r,c in g); lab=cnt.most_common(1)[0][0]
  for r,c in g:
   for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
    x,y=r+dr,c+dc
    if 0<=x<H and 0<=y<W and grid[x,y]==target and (x,y) not in core:
     labels_seed.setdefault((x,y),set()).add(lab)
 # connected components branch target excluding core
 seen=set(); comps=[]
 for r,c in zip(*np.where(grid==target)):
  p=(int(r),int(c))
  if p in core or p in seen: continue
  q=[p];seen.add(p);reg=[]
