   a,b=q.pop();reg.append((a,b))
   for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
    x,y=a+dr,b+dc
    if 0<=x<H and 0<=y<W and grid[x,y]==target and (x,y) not in core and (x,y) not in seen:
     seen.add((x,y));q.append((x,y))
